// Réglages de presti-sauvegarde (brief : plans/011-cadrage-01-11/briefs/c4-n8n-sauvegarde.md). Rien n'est lu en base, rien n'est écrit.
// Le jour est celui de Paris ; le dossier et la conservation sont des défauts du lot, à valider par Benj.
const maintenant = new Date();
const jour = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Paris' }).format(maintenant);
return [{ json: { jour, debut_ms: maintenant.getTime(), dossier: '/home/usine/sauvegardes-presti', conservation_jours: 14 } }];

// Lit la sortie de la commande de sauvegarde (scripts/sauvegarde.mjs, tâche 032-020).
// Codes : 0 réussie ; 75 un autre passage tournait déjà (flock) ; 124 ou 137 délai dépassé ; 2 préconditions absentes ; 1 refus ou échec.
const sortie = $input.first().json;
const code = typeof sortie.code === 'number' ? sortie.code : null;
const stdout = String(sortie.stdout ?? '');
const stderr = String(sortie.stderr ?? (typeof sortie.error === 'string' ? sortie.error : (sortie.error && sortie.error.message) || ''));
const net = (t) => String(t).replace(/[A-Za-z0-9_+\/=-]{32,}/g, '…').replace(/\s+/g, ' ').trim().slice(0, 200);
const m = stdout.match(/✅ (\S+) — (\d+) tables, (\d+) lignes, (\d+) comptes, (\d+) Ko, (\d+) s/);
const ok = code === 0 && m !== null;
let raison = '';
if (!ok) {
  if (code === 75) raison = 'une sauvegarde tournait déjà (verrou)';
  else if (code === 124 || code === 137) raison = 'délai dépassé (900 s), commande coupée';
  else if (code === 2) raison = 'préconditions absentes (clé de service ou clé publique de sauvegarde)';
  else if (code === 0) raison = 'la commande a rendu 0 sans la ligne de bilan attendue';
  else if (code === null) raison = 'la commande n\'a pas pu être lancée (connexion SSH)';
  else raison = 'la sauvegarde a refusé ou échoué (code ' + code + ')';
  const detail = net(stderr || stdout.split('\n').filter(Boolean).pop() || '');
  if (detail) raison += ' — ' + detail;
}
return [{ json: {
  etape: 'sauvegarde',
  ok,
  code,
  archive: m ? m[1].split('/').pop() : null,
  tables: m ? Number(m[2]) : null,
  lignes: m ? Number(m[3]) : null,
  comptes: m ? Number(m[4]) : null,
  ko: m ? Number(m[5]) : null,
  secondes: m ? Number(m[6]) : null,
  raison,
} }];

// Bilan du passage : la sauvegarde ET sa relecture doivent être vertes, et la relecture doit porter sur l'archive qui vient d'être écrite.
const s = $('Lire la sauvegarde').first().json;
const reg = $('Réglages de la sauvegarde').first().json;
let r = null;
try { r = $('Relire la dernière archive').first().json; } catch (e) { r = null; }
const net = (t) => String(t).replace(/[A-Za-z0-9_+\/=-]{32,}/g, '…').replace(/\s+/g, ' ').trim().slice(0, 200);
let etapeEnEchec = null;
let raison = '';
if (!s.ok) {
  etapeEnEchec = 'sauvegarde';
  raison = s.raison;
} else if (r === null) {
  etapeEnEchec = 'relecture';
  raison = 'la relecture n\'a pas tourné';
} else {
  const sortie = String(r.stdout ?? '');
  const verif = sortie.match(/▶ Vérification de (\S+)/);
  const man = sortie.match(/manifeste version (\d+), fait le (\S+) : (\d+) tables, (\d+) lignes, (\d+) comptes/);
  const lueOk = r.code === 0 && sortie.includes('archive relue, comptes égaux');
  if (!lueOk) {
    etapeEnEchec = 'relecture';
    const detail = net(String(r.stderr ?? '') || sortie.split('\n').filter((l) => l.includes('❌')).slice(0, 2).join(' ') || (typeof r.error === 'string' ? r.error : ''));
    raison = 'la relecture est rouge (code ' + (typeof r.code === 'number' ? r.code : 'inconnu') + ')' + (detail ? ' — ' + detail : '');
  } else if (!verif || verif[1].split('/').pop() !== s.archive) {
    etapeEnEchec = 'relecture';
    raison = 'la relecture n\'a pas porté sur l\'archive du passage (' + s.archive + ')';
  } else if (!man || Number(man[3]) !== s.tables) {
    etapeEnEchec = 'relecture';
    raison = 'le manifeste relu ne compte pas les mêmes tables que la sauvegarde (' + (man ? man[3] : 'illisible') + ' contre ' + s.tables + ')';
  }
}
const ok = etapeEnEchec === null;
return [{ json: {
  ok,
  jour: reg.jour,
  etape_en_echec: etapeEnEchec,
  raison,
  archive: s.archive,
  tables: s.tables,
  lignes: s.lignes,
  comptes: s.comptes,
  ko: s.ko,
  secondes_sauvegarde: s.secondes,
  duree_totale_s: Math.round((Date.now() - reg.debut_ms) / 1000),
} }];
